{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    required_keys = ('threshold', 'calls')
    if not all(k in case for k in required_keys):
        raise ValueError("case missing threshold or calls")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    call_ids_seen = set()
    diagnostics = []
    accepted = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be a dict")
        required_call_keys = ('call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable')
        if not all(k in call for k in required_call_keys):
            raise ValueError(f"call missing required key")
        cid = call['call_id']
        if not isinstance(cid, str) or not cid:
            raise ValueError(f"call_id must be a non-empty string")
        if cid in call_ids_seen:
            raise ValueError(f"duplicate call_id {cid}")
        call_ids_seen.add(cid)
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError("loss values must be numbers")
        if not isinstance(tokens, int) or tokens <= 0:
            raise ValueError("prediction_tokens must be positive integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")
        gain = loss_without - loss_with
        normalized_gain = gain / tokens
        satisfies = parseable and normalized_gain >= threshold
        diag = {
            'call_id': cid,
            'normalized_gain': round(normalized_gain, 4),
            'parseable': parseable,
            'accepted': satisfies
        }
        diagnostics.append(diag)
        if satisfies:
            accepted.append(cid)
    result = {
        'accepted': accepted,
        'diagnostics': diagnostics
    }
    return result
